import {validateScenarioSpeed} from './scenario-speed.js?v=scenario-stages-1';
import {validateScenarioArea,scenarioAreaLabel} from './scenario-area.js?v=scenario-stages-1';
import {validateScenarioStory} from './scenario-story.js?v=scenario-stages-1';
import {validateEventDefinitions,scenarioEventGoals} from './scenario-events.js?v=scenario-stages-1';
import {CUSTOM_METRICS} from './scenario-metrics.js?v=scenario-stages-1';
export {CUSTOM_METRICS} from './scenario-metrics.js?v=scenario-stages-1';
export function validateCustomDefinition(v){if(!v||typeof v.title!=='string'||!v.title.trim()||v.title.length>60||/[\x00-\x1f]/.test(v.title)||!Number.isInteger(v.months)||v.months<12||v.months>1200||!Array.isArray(v.objectives)||v.objectives.length<1||v.objectives.length>4)throw Error('Choose a title, a 12–1200 month deadline, and one to four goals.');const objectiveMode=v.objectiveMode??'together';if(!['together','sequence'].includes(objectiveMode))throw Error('Choose simultaneous goals or sequential stages.');const eventMode=v.eventMode??'monthly';if(!['monthly','together'].includes(eventMode))throw Error('Choose one event per month or grouped actions.');const holdMonths=v.holdMonths??1;if(!Number.isInteger(holdMonths)||holdMonths<1||holdMonths>v.months)throw Error('Hold goals for 1 to the deadline’s number of months.');if(objectiveMode==='sequence'&&holdMonths*v.objectives.length>v.months)throw Error('The deadline must allow enough months to hold every stage.');const seen=new Set();const objectives=v.objectives.map(o=>{const m=Object.hasOwn(CUSTOM_METRICS,o?.metric)?CUSTOM_METRICS[o.metric]:null;const area=validateScenarioArea(o.area,m),key=o.metric+JSON.stringify(area);if(!m||objectiveMode==='together'&&seen.has(key)||!Number.isFinite(o.target)||o.target<(m.min||0)||o.target>m.max||m.integer&&!Number.isInteger(o.target))throw Error('Choose distinct goals with targets inside their allowed ranges.');seen.add(key);return{metric:o.metric,target:o.target,...(area?{area}:{})};});return{objectiveMode,eventMode,speed:validateScenarioSpeed(v.speed),...validateScenarioStory(v),title:v.title.trim(),months:v.months,holdMonths,objectives,events:validateEventDefinitions(v.events,v.months,eventMode)};}
function objectiveGoal(c,o){const m=CUSTOM_METRICS[o.metric],value=m.read(c,o.area);return{...(o.area?{area:o.area}:{}),title:`${m.name}${scenarioAreaLabel(o.area)}: ${m.states?m.states[o.target]:m.direction+' '+o.target.toLocaleString()}`,done:m.direction==='equals'?value===o.target:m.direction==='at least'?value>=o.target:value<=o.target,detail:`Current: ${m.states?m.states[value]:value.toLocaleString(undefined,{maximumFractionDigits:1})}`};}
export function customCurrentGoals(c){const s=c.scenario,sequence=s.definition.objectiveMode==='sequence',completed=s.stageCompletedMonths?.length||0;return [...scenarioEventGoals(c),...s.definition.objectives.map((o,i)=>{const g=objectiveGoal(c,o);if(!sequence)return g;return {...g,title:`Stage ${i+1} · ${g.title}`,done:i<completed,detail:i<completed?`Completed in challenge month ${s.stageCompletedMonths[i]-s.startMonth}. Completion is retained.`:i===completed?`${g.detail} · Hold: ${s.streak} / ${s.definition.holdMonths} consecutive months.`:'Locked until the preceding stage is completed.'};})];}
export function attachCustomScenario(c,definition){if(c.emergency.active)throw Error('Finish the active emergency before creating a challenge.');const d=validateCustomDefinition(definition);c.scenario={id:'custom',definition:d,events:d.events.map(()=>({status:'pending',month:null,runs:0})),stageCompletedMonths:[],status:'playing',startMonth:c.month,lastChecked:c.month,streak:0,eventFired:false,endedMonth:null,rank:null};return c.scenario;}

export function advanceCustomStreak(c){const s=c.scenario;if(s.definition.objectiveMode==='sequence'){const completed=s.stageCompletedMonths.length;if(completed>=s.definition.objectives.length)return;s.streak=!c.emergency.active&&objectiveGoal(c,s.definition.objectives[completed]).done?Math.min(s.definition.holdMonths,s.streak+1):0;if(s.streak>=s.definition.holdMonths){s.stageCompletedMonths.push(c.month);s.streak=0;}return;}s.streak=customCurrentGoals(c).every(g=>g.done)?Math.min(s.definition.holdMonths,s.streak+1):0;}
export function customGoals(c){const s=c.scenario,goals=customCurrentGoals(c);if(s.definition.objectiveMode==='sequence'){const completed=s.stageCompletedMonths.length;goals.unshift({title:`Complete ${s.definition.objectives.length} stages in order`,done:completed===s.definition.objectives.length,detail:`${completed} / ${s.definition.objectives.length} completed. Each stage needs ${s.definition.holdMonths} consecutive monthly checks. Finished stages stay complete; required events must still finish before victory.`});}else if(s.definition.holdMonths>1)goals.unshift({title:`Hold every goal for ${s.definition.holdMonths} consecutive months`,done:s.streak>=s.definition.holdMonths,detail:`${s.streak} / ${s.definition.holdMonths} months. Missing a goal resets progress; required events and emergency response must finish before the streak begins.`});return goals;}
export function validateStageProgress(v,definition,startMonth,lastChecked,streak,status){if(definition.objectiveMode==='sequence'&&!Array.isArray(v))throw Error('Missing scenario stage progress.');const stages=v??[];if(!Array.isArray(stages)||stages.length>definition.objectives.length||definition.objectiveMode!=='sequence'&&stages.length||stages.some((month,i)=>!Number.isInteger(month)||month>(lastChecked)||month-(i?stages[i-1]:startMonth)<definition.holdMonths)||definition.objectiveMode==='sequence'&&(streak>=definition.holdMonths||streak>lastChecked-(stages.at(-1)??startMonth)||stages.length===definition.objectives.length&&streak!==0||status==='won'&&stages.length!==definition.objectives.length))throw Error('Invalid scenario stage progress.');return [...stages];}
